package com.ultras.bans.service;
import com.ultras.bans.ULTRASBansPlugin; import org.bukkit.*; import org.bukkit.entity.Player; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public final class JailService { private final ULTRASBansPlugin plugin; private final Set<UUID> jailed=ConcurrentHashMap.newKeySet(); private Location jail; public JailService(ULTRASBansPlugin p){plugin=p;} public void load(){var c=plugin.getConfig();if(c.contains("jail.world")){World w=Bukkit.getWorld(c.getString("jail.world"));if(w!=null)jail=new Location(w,c.getDouble("jail.x"),c.getDouble("jail.y"),c.getDouble("jail.z"),(float)c.getDouble("jail.yaw"),(float)c.getDouble("jail.pitch"));}} public void setLocation(Player p){jail=p.getLocation();plugin.getConfig().set("jail.world",jail.getWorld().getName());plugin.getConfig().set("jail.x",jail.getX());plugin.getConfig().set("jail.y",jail.getY());plugin.getConfig().set("jail.z",jail.getZ());plugin.getConfig().set("jail.yaw",jail.getYaw());plugin.getConfig().set("jail.pitch",jail.getPitch());plugin.saveConfig();p.sendMessage(com.ultras.bans.utility.Text.c("<green>✓</green> ᴜʟᴛʀᴀs | Jail location saved."));} public boolean hasLocation(){return jail!=null;} public void set(Player p,boolean v){if(v){plugin.jailInventory().capture(p);if(jail!=null)p.teleport(jail);jailed.add(p.getUniqueId());p.sendMessage(com.ultras.bans.utility.Text.c("<red>ᴜʟᴛʀᴀs</red> | You are jailed."));}else{plugin.jailInventory().restore(p);jailed.remove(p.getUniqueId());p.sendMessage(com.ultras.bans.utility.Text.c("<green>✓</green> ᴜʟᴛʀᴀs | You are unjailed."));}} public boolean isJailed(UUID u){return jailed.contains(u);} public void move(Player p){if(isJailed(p.getUniqueId())&&jail!=null&&p.getLocation().distanceSquared(jail)>2500)p.teleport(jail);} }
